import { readFileSync } from "node:fs";
import { resolve } from "node:path";

import { secp256k1 } from "@noble/curves/secp256k1.js";
import { bytesToHex, hexToBytes } from "@noble/hashes/utils.js";
import { expect, test } from "vite-plus/test";

import { SparkError, SparkInputError } from "../src/errors/index.ts";
import { createLnurlAuthSigner, lnurlAuthRootKey } from "../src/signer/index.ts";

// vectors/lnurl-auth.json — generated by crates/interop/tests/lnurl_auth.rs,
// which replays the Breez SDK LUD-05 derivation (m/138' root, hashing key at
// m/138'/0, HMAC-SHA256 over the lowercase domain, four big-endian u32 path
// elements, DER signature over the raw 32-byte k1).

type VectorCase = {
  seed: string;
  domain: string;
  domainInput?: string;
  k1: string;
  rootKey: string;
  hashingKey: string;
  hmac: string;
  path: number[];
  linkingKey: string;
  signature: string;
};

const { cases } = JSON.parse(
  readFileSync(resolve(import.meta.dirname, "../../../vectors/lnurl-auth.json"), "utf8"),
) as { cases: VectorCase[] };

test("lnurlAuthRootKey derives the m/138' extended private key from the seed", () => {
  for (const c of cases) {
    expect(bytesToHex(lnurlAuthRootKey(hexToBytes(c.seed)))).toBe(c.rootKey);
  }
});

test("linkingKey derives the per-domain compressed public key", async () => {
  await Promise.all(
    cases.map(async (c) => {
      const signer = createLnurlAuthSigner({ rootKey: hexToBytes(c.rootKey) });
      try {
        expect(bytesToHex(await signer.linkingKey(c.domain))).toBe(c.linkingKey);
      } finally {
        signer.dispose();
      }
    }),
  );
});

test("sign produces the deterministic DER signature over k1", async () => {
  await Promise.all(
    cases.map(async (c) => {
      const signer = createLnurlAuthSigner({ rootKey: hexToBytes(c.rootKey) });
      try {
        const { linkingKey, signature } = await signer.sign({
          domain: c.domain,
          k1: hexToBytes(c.k1),
        });
        expect(bytesToHex(linkingKey)).toBe(c.linkingKey);
        expect(bytesToHex(signature)).toBe(c.signature);
      } finally {
        signer.dispose();
      }
    }),
  );
});

test("signatures verify against the linking key over the raw k1 digest", async () => {
  const c = cases[0]!;
  const signer = createLnurlAuthSigner({ rootKey: hexToBytes(c.rootKey) });
  const { linkingKey, signature } = await signer.sign({
    domain: c.domain,
    k1: hexToBytes(c.k1),
  });
  expect(
    secp256k1.verify(signature, hexToBytes(c.k1), linkingKey, { prehash: false, format: "der" }),
  ).toBe(true);
  signer.dispose();
});

test("domainInput stays uppercase in the vector but the signer rejects it", async () => {
  const c = cases.find((entry) => entry.domainInput !== undefined)!;
  const signer = createLnurlAuthSigner({ rootKey: hexToBytes(c.rootKey) });
  await expect(signer.sign({ domain: c.domainInput!, k1: hexToBytes(c.k1) })).rejects.toThrow(
    SparkInputError,
  );
  // The lowercased input derives the documented linking key.
  expect(bytesToHex(await signer.linkingKey(c.domainInput!.toLowerCase()))).toBe(c.linkingKey);
  signer.dispose();
});

test("rejects bad inputs", async () => {
  const signer = createLnurlAuthSigner({ rootKey: hexToBytes(cases[0]!.rootKey) });
  await expect(signer.linkingKey("")).rejects.toThrow(SparkInputError);
  await expect(signer.linkingKey("EXAMPLE.com")).rejects.toThrow(SparkInputError);
  await expect(signer.linkingKey("bad..host")).rejects.toThrow(SparkInputError);
  await expect(signer.linkingKey("-lead.com")).rejects.toThrow(SparkInputError);
  await expect(signer.linkingKey("trail-.com")).rejects.toThrow(SparkInputError);
  await expect(
    signer.sign({ domain: "example.com", k1: hexToBytes("aa".repeat(31)) }),
  ).rejects.toThrow(SparkInputError);
  signer.dispose();
});

test("rejects malformed root keys", () => {
  expect(() => createLnurlAuthSigner({ rootKey: new Uint8Array(63) })).toThrow(SparkInputError);
  expect(() => createLnurlAuthSigner({ rootKey: new Uint8Array(64) })).toThrow(SparkInputError); // zero private half
  expect(() => lnurlAuthRootKey(new Uint8Array(0))).toThrow(SparkInputError);
});

test("dispose wipes the root key and later calls reject", async () => {
  const rootKey = lnurlAuthRootKey(hexToBytes(cases[0]!.seed));
  const signer = createLnurlAuthSigner({ rootKey });
  rootKey.fill(0); // the signer owns its copies; the caller's buffer can be wiped
  const { linkingKey } = await signer.sign({ domain: "site.com", k1: hexToBytes(cases[0]!.k1) });
  expect(linkingKey).toHaveLength(33);
  signer.dispose();
  await expect(signer.linkingKey("site.com")).rejects.toThrow(SparkError);
  await expect(signer.sign({ domain: "site.com", k1: hexToBytes(cases[0]!.k1) })).rejects.toThrow(
    SparkError,
  );
  signer.dispose(); // idempotent
});
